def pad_with_char(s, width, ch):
    if len(s) >= width:
        return s
    return s + ch * (width - len(s))

def bottom_k_by_value(d, k):
    if k <= 0:
        return []
    items = sorted(d.items(), key=lambda kv: (kv[1], kv[0]))
    return items[:k]

def sanitize_filename_windows(name):
    reserved = '<>:"/\\|?*'
    result = ''.join('_' if c in reserved else c for c in name)
    return result.rstrip(' .')

def mod_pow(base, exp, mod):
    result = 1 % mod
    b = base % mod
    e = exp
    while e > 0:
        if e & 1:
            result = (result * b) % mod
        b = (b * b) % mod
        e >>= 1
    return result

def is_valid_gray_code_step(a, b):
    if len(a) != len(b):
        return False
    valid = set('01')
    if any(c not in valid for c in a) or any(c not in valid for c in b):
        return False
    diff = sum(1 for x, y in zip(a, b) if x != y)
    return diff == 1

import re

def is_valid_dashed_phone_number(s):
    return re.fullmatch(r'[2-9]\d{2}-\d{3}-\d{4}', s) is not None

from datetime import date, timedelta

def subtract_days_from_date(y, m, d, n):
    result = date(y, m, d) - timedelta(days=n)
    return (result.year, result.month, result.day)

def shift_right_and_fill(lst, n, fill):
    length = len(lst)
    if n <= 0:
        return list(lst)
    if n >= length:
        return [fill] * length
    return [fill] * n + lst[:length - n]

def classify_char_string(s):
    vowels = set('aeiouAEIOU')
    result = []
    for c in s:
        if c in vowels:
            result.append('V')
        elif c.isalpha():
            result.append('C')
        elif c.isdigit():
            result.append('D')
        else:
            result.append('O')
    return ''.join(result)

def weekend_count_given_start_weekday(start_weekday, num_days):
    count = 0
    for i in range(num_days):
        wd = (start_weekday + i) % 7
        if wd == 5 or wd == 6:
            count += 1
    return count
